package finance.governance;
import finance.company.*;import finance.stock.*;import java.math.BigInteger;import java.util.UUID;
public final class GovernanceAuthorizationService{private GovernanceAuthorizationService(){}public static boolean mayManage(UUID actor,UUID companyId){Company c=CompanyManager.getCompany(companyId);return actor!=null&&c!=null&&(actor.equals(c.getOwnerId())||actor.equals(CorporateActionManager.controllers().get(companyId)));}public static boolean mayCreateProposal(UUID actor,UUID companyId){if(mayManage(actor,companyId))return true;Stock s=StockMarketManager.getStockByCompanyId(companyId);if(actor==null||s==null||s.getVotingShares()<=0)return false;long q=StockPortfolioManager.getHolding(actor,s.getSymbol()).getQuantity();return q>0&&BigInteger.valueOf(q).multiply(BigInteger.valueOf(4)).compareTo(BigInteger.valueOf(s.getVotingShares()))>=0;}}
